package fizeau

import (
	"context"
	"fmt"
	"io"
	"path/filepath"
	"sync"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	claudeharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/claude"
	codexharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/codex"
	geminiharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/gemini"
	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
	"github.com/DocumentDrivenDX/fizeau/internal/serviceimpl"
	sessionusage "github.com/DocumentDrivenDX/fizeau/internal/session"
)

// FizeauService is the entire public Go surface of the fizeau module.
// See CONTRACT-003 for the full specification.
type FizeauService interface {
	Execute(ctx context.Context, req ServiceExecuteRequest) (<-chan ServiceEvent, error)
	TailSessionLog(ctx context.Context, sessionID string) (<-chan ServiceEvent, error)
	ListHarnesses(ctx context.Context) ([]HarnessInfo, error)
	ListProviders(ctx context.Context) ([]ProviderInfo, error)
	ListModels(ctx context.Context, filter ModelFilter) ([]ModelInfo, error)
	ListProfiles(ctx context.Context) ([]ProfileInfo, error)
	ResolveProfile(ctx context.Context, name string) (*ResolvedProfile, error)
	ProfileAliases(ctx context.Context) (map[string]string, error)
	HealthCheck(ctx context.Context, target HealthTarget) error
	ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error)
	RecordRouteAttempt(ctx context.Context, attempt RouteAttempt) error
	RouteStatus(ctx context.Context) (*RouteStatusReport, error)

	// Historical session-log projections. CONTRACT-003 owns these so CLI
	// subcommands such as log/replay/usage do not need to read the
	// internal session-log JSONL schema.
	UsageReport(ctx context.Context, opts UsageReportOptions) (*UsageReport, error)
	ListSessionLogs(ctx context.Context) ([]SessionLogEntry, error)
	WriteSessionLog(ctx context.Context, sessionID string, w io.Writer) error
	ReplaySession(ctx context.Context, sessionID string, w io.Writer) error
}

// ServiceConfig provides provider and routing data to the service without
// creating an import cycle from the root package into agent/config.
// Callers wrap their loaded *config.Config in a type that satisfies this interface.
type ServiceConfig interface {
	// ProviderNames returns provider names in stable order (default first).
	ProviderNames() []string
	// DefaultProviderName returns the name of the configured default provider.
	DefaultProviderName() string
	// Provider returns the raw config values for a named provider.
	Provider(name string) (ServiceProviderEntry, bool)
	// HealthCooldown returns the configured cooldown duration (0 = use default 30s).
	HealthCooldown() time.Duration
	// WorkDir is the base directory for file-backed health state.
	WorkDir() string
	// SessionLogDir returns the configured sessions directory.
	SessionLogDir() string
}

// ServiceProviderEntry carries the minimal provider data the service needs.
type ServiceProviderEntry struct {
	Type           string // "openai" | "openrouter" | "lmstudio" | "llama-server" | "omlx" | "lucebox" | "vllm" | "rapid-mlx" | "ollama" | "anthropic"
	BaseURL        string
	ServerInstance string
	Endpoints      []ServiceProviderEndpoint
	APIKey         string
	Headers        map[string]string
	Model          string // configured default model (may be empty)
	// ContextWindow is the configured provider-side context override.
	ContextWindow int
	// ConfigError marks this provider entry invalid while allowing the rest of
	// the service config to load. Invalid providers are reported in status
	// surfaces and excluded from routing.
	ConfigError string
	// DailyTokenBudget is the operator-configured per-UTC-day token budget
	// (request + response) for this provider. Zero means no local burn-rate
	// prediction; the provider's own quota signal still applies.
	DailyTokenBudget int
}

// ServiceProviderEndpoint is one configured provider serving endpoint.
type ServiceProviderEndpoint struct {
	Name           string
	BaseURL        string
	ServerInstance string
}

// ServiceOptions configures a FizeauService instance.
//
// seamOptions is embedded so production builds (no testseam tag) get an
// empty struct — making it a compile-time error to set seam fields without
// the build tag. Test builds inherit the four CONTRACT-003 seams
// (FakeProvider, PromptAssertionHook, CompactionAssertionHook,
// ToolWiringHook) automatically.
type ServiceOptions struct {
	seamOptions

	ConfigPath string    // optional override; default $XDG_CONFIG_HOME/fizeau/config.yaml
	Logger     io.Writer // optional; agent writes structured session logs internally regardless

	// ServiceConfig, when non-nil, supplies provider and routing data for
	// ListProviders and HealthCheck. Pass a value wrapping the loaded config.
	// When nil, those methods return an error.
	ServiceConfig ServiceConfig

	// QuotaRefreshDebounce is the minimum interval between live quota probes for
	// a primary subscription harness. Zero uses the service default.
	QuotaRefreshDebounce time.Duration
	// QuotaRefreshStartupWait bounds startup waiting when the durable quota
	// cache is missing, stale, or incomplete. Zero uses the service default.
	QuotaRefreshStartupWait time.Duration
	// QuotaRefreshInterval enables periodic refresh for long-running server
	// processes. Zero disables the timer; cache refresh still happens on startup
	// and service activity.
	QuotaRefreshInterval time.Duration
	// QuotaRefreshContext optionally cancels the periodic server refresh worker.
	// When nil, the worker uses context.Background().
	QuotaRefreshContext context.Context

	// CatalogProbeTimeout bounds live /v1/models discovery during routing.
	// Zero uses the service default of 2s.
	CatalogProbeTimeout time.Duration
	// CatalogRefreshTimeout bounds stale-while-revalidate catalog refreshes.
	// Zero uses the service default of 30s.
	CatalogRefreshTimeout time.Duration

	// LocalCostUSDPer1kTokens is the operator-supplied electricity/operations
	// estimate for local endpoint providers under the embedded agent harness.
	// Zero means local endpoint cost is unknown.
	LocalCostUSDPer1kTokens float64
	// SubscriptionCostCurve optionally overrides the default subscription
	// effective-cost curve used by routing.
	SubscriptionCostCurve *SubscriptionCostCurve

	// SessionLogDir overrides the directory used by historical session-log
	// projections (UsageReport, ListSessionLogs, WriteSessionLog,
	// ReplaySession). Empty falls back to ServiceConfig.SessionLogDir().
	// Per-Execute requests still set their own
	// ServiceExecuteRequest.SessionLogDir.
	SessionLogDir string

	// StaleHarnessReaperGrace is the minimum age before a startup reaper may
	// terminate an owned subprocess record. Zero uses the default grace window.
	StaleHarnessReaperGrace time.Duration
}

// SubscriptionCostCurve tunes effective subscription cost by quota utilization.
// Thresholds are percentages used, and multipliers are applied to the
// equivalent pay-per-token catalog rate.
type SubscriptionCostCurve struct {
	FreeUntilPercent   int
	LowUntilPercent    int
	MediumUntilPercent int
	LowMultiplier      float64
	MediumMultiplier   float64
	HighMultiplier     float64
}

// QuotaState is a live quota snapshot for a harness. Nil means not applicable.
type QuotaState struct {
	Windows    []harnesses.QuotaWindow `json:"windows"`
	CapturedAt time.Time               `json:"captured_at"`
	Fresh      bool                    `json:"fresh"`
	Source     string                  `json:"source,omitempty"`
	Status     string                  `json:"status,omitempty"` // ok|stale|unavailable|unauthenticated|unknown
	LastError  *StatusError            `json:"last_error,omitempty"`
}

// StatusError describes the most recent normalized status error for a harness,
// provider, or endpoint.
type StatusError struct {
	Type      string    // unavailable|unauthenticated|error
	Detail    string    // human-readable detail, safe for diagnostics
	Source    string    // config path, endpoint, cache path, or probe name
	Timestamp time.Time // zero when the source did not include a timestamp
}

// AccountStatus describes authentication/account state without exposing
// provider-specific native files to consumers.
type AccountStatus struct {
	Authenticated   bool
	Unauthenticated bool
	Email           string
	PlanType        string
	OrgName         string
	Source          string
	CapturedAt      time.Time
	Fresh           bool
	Detail          string
}

// UsageWindow describes normalized usage attribution over a time window.
// Empty token/cost totals mean the service has no historical usage source yet.
type UsageWindow struct {
	Name                string
	Source              string
	CapturedAt          time.Time
	Fresh               bool
	InputTokens         int
	OutputTokens        int
	TotalTokens         int
	CacheReadTokens     int
	CacheWriteTokens    int
	ReasoningTokens     int
	CostUSD             float64
	KnownCostUSD        *float64
	UnknownCostSessions int
}

// EndpointStatus describes one configured provider endpoint probe.
type EndpointStatus struct {
	Name           string
	BaseURL        string
	ServerInstance string
	ProbeURL       string
	Status         string // connected|unreachable|unauthenticated|error|unknown
	Source         string

	QuotaTrend       string
	// Capability is a coarse capability score derived from the candidate's
	// cost class / surface (higher = more capable).
	Capability float64
	// ContextHeadroom is the remaining context after subtracting the request's
	// minimum required prompt window. Zero means unknown or no spare room.
	ContextHeadroom int
}

const (
	ContextSourceProviderAPI    = "provider_api"
	ContextSourceProviderConfig = "provider_config"
	ContextSourceCatalog        = "catalog"
	ContextSourceDefault        = "default"
	ContextSourceUnknown        = "unknown"
)

// RouteStickyState describes sticky routing evidence without exposing the
// underlying key.
type RouteStickyState struct {
	KeyPresent     bool    `json:"key_present,omitempty"`
	Assignment     string  `json:"assignment,omitempty"`
	ServerInstance string  `json:"server_instance,omitempty"`
	Reason         string  `json:"reason,omitempty"`
	Bonus          float64 `json:"bonus"`
}

// RouteUtilizationState summarizes the live utilization sample associated
// with a candidate or selected endpoint.
type RouteUtilizationState struct {
	Source         string    `json:"source,omitempty"`
	Freshness      string    `json:"freshness,omitempty"`
	ActiveRequests *int      `json:"active_requests,omitempty"`
	QueuedRequests *int      `json:"queued_requests,omitempty"`
	MaxConcurrency *int      `json:"max_concurrency,omitempty"`
	CachePressure  *float64  `json:"cache_pressure,omitempty"`
	ObservedAt     time.Time `json:"observed_at,omitempty"`
}

// RouteAttempt is caller feedback about one attempted route candidate.
// Status="success" clears matching active failures; any other non-empty status
// records a same-process failure until the service health cooldown expires.
type RouteAttempt struct {
	Harness   string
	Provider  string
	Model     string
	Endpoint  string
	Status    string
	Reason    string
	Error     string
	Duration  time.Duration
	Timestamp time.Time // zero = time.Now()
}

// RouteStatusReport is returned by RouteStatus.
//
// RoutingQuality (ADR-006 §5) is the operator-facing measure of how often
// auto-routing produces an acceptable decision. It is intentionally
// distinct from per-(provider, model) provider-reliability surfaced on
// each RouteCandidateStatus: the two compose, and conflating them is the
// UI bug ADR-006 fixes.
type RouteStatusReport struct {
	Routes          []RouteStatusEntry
	GeneratedAt     time.Time
	GlobalCooldowns []CooldownState
	// RoutingQuality holds the three first-class routing-quality metrics
	// over a recent window (last RouteStatusRoutingQualityWindow requests).
	RoutingQuality RoutingQualityMetrics
}

// RouteStatusRoutingQualityWindow caps how many recent Execute calls
// contribute to RouteStatusReport.RoutingQuality. ADR-006 §5 calls for a
// "recent window"; the constant is exported so operator UIs can label the
// metric appropriately.
const RouteStatusRoutingQualityWindow = 100

// RouteStatusEntry describes the live provider candidates serving one model.
type RouteStatusEntry struct {
	Model                  string
	Strategy               string // informational; route tables are not user-authored
	SelectedEndpoint       string
	SelectedServerInstance string
	Sticky                 RouteStickyState
	Candidates             []RouteCandidateStatus
	LastDecision           *RouteDecision // most recent ResolveRoute result for this key (cached)
	LastDecisionAt         time.Time
}

// RouteCandidateStatus describes a single live provider/model candidate.
//
// ProviderReliabilityRate is the per-(provider, model) observed completion
// rate (the legacy "success rate" metric). Per ADR-006 §5 it is labeled
// "provider reliability" to distinguish it from RoutingQualityMetrics on
// the parent report — the two metrics measure different things and are
// surfaced as separate fields.
type RouteCandidateStatus struct {
	Provider                string
	Model                   string
	ServerInstance          string
	Priority                int
	Healthy                 bool
	Cooldown                *CooldownState
	RecentLatencyMS         float64 // observation-derived; 0 when unavailable
	ProviderReliabilityRate float64 // 0-1; 0 when unavailable. Legacy success-rate field, relabeled per ADR-006 §5 to disambiguate from routing-quality.
}

// ServiceEvent is a contract-level event (mirrors harnesses.Event).
type ServiceEvent = harnesses.Event

// ServiceExecuteRequest is the public ExecuteRequest type per CONTRACT-003.
// See docs/helix/02-design/contracts/CONTRACT-003-fizeau-service.md
// (§"Public types") for the canonical shape; this struct is its in-process
// twin under the agent module.
type ServiceExecuteRequest struct {
	Prompt            string
	SystemPrompt      string
	Model             string
	Provider          string
	Harness           string
	ModelRef          string
	Profile           string
	WorkDir           string
	Temperature       *float32
	TopP              *float64
	TopK              *int
	MinP              *float64
	RepetitionPenalty *float64
	Seed              *int64
	// SamplingSource is the comma-separated layer attribution produced by
	// internal/sampling.Resolve. Plumbed through to the llm.request
	// telemetry event for ADR-007 override-tracking; never on the wire.
	SamplingSource string
	Reasoning      Reasoning
	NoStream       bool
	Permissions    string
	// Tools overrides the built-in native agent tool set when Harness is
	// "fiz". Nil uses the native built-ins for ToolPreset and WorkDir.
	Tools []Tool
	// ToolPreset is passed through to BuiltinToolsForPreset when Tools is nil.
	// Empty uses the default tool set.
	ToolPreset string

	Components    routeStatusComponents            `json:"components"`
	Utilization   rootfizeau.RouteUtilizationState `json:"utilization,omitempty"`
	Eligible      bool                             `json:"eligible"`
	FilterReason  string                           `json:"filter_reason"`
	Reason        string                           `json:"reason,omitempty"`
	CostSource    string                           `json:"cost_source,omitempty"`
	Winner        bool                             `json:"winner"`
}

type routeStatusPowerPolicy struct {
	Profile  string `json:"profile,omitempty"`
	MinPower int    `json:"min_power,omitempty"`
	MaxPower int    `json:"max_power,omitempty"`
}

type routeStatusOutput struct {
	Profile          string                           `json:"profile,omitempty"`
	Model            string                           `json:"model,omitempty"`
	ModelRef         string                           `json:"model_ref,omitempty"`
	Provider         string                           `json:"provider,omitempty"`
	Harness          string                           `json:"harness,omitempty"`
	MinPower         int                              `json:"min_power,omitempty"`
	MaxPower         int                              `json:"max_power,omitempty"`
	PowerPolicy      routeStatusPowerPolicy           `json:"power_policy,omitempty"`
	SelectedEndpoint string                           `json:"selected_endpoint,omitempty"`
	Sticky           rootfizeau.RouteStickyState      `json:"sticky,omitempty"`
	Utilization      rootfizeau.RouteUtilizationState `json:"utilization,omitempty"`
	Winner           *routeStatusCandidate            `json:"winner,omitempty"`
	Candidates       []routeStatusCandidate           `json:"candidates"`
	Error            string                           `json:"error,omitempty"`
}

// cmdRouteStatus reports the routing engine's eligible-candidate trace for a
// requested intent (per ADR-005 §5). It calls service.ResolveRoute rather than
// enumerating route tables; score components and filter reasons come from the
// engine itself, not a parallel CLI implementation.
func cmdRouteStatus(workDir string, args []string) int {
	fs := flag.NewFlagSet("route-status", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	profile := fs.String("profile", "", "Routing profile (named power shortcut; use --min-power / --max-power for exact bounds)")
	model := fs.String("model", "", "Pin a specific model")
	modelRef := fs.String("model-ref", "", "Model catalog reference (alias, profile, or canonical target; deprecated targets fail with replacement guidance)")
	provider := fs.String("provider", "", "Pin a specific provider")
	harness := fs.String("harness", "", "Pin a specific harness")
	minPower := fs.Int("min-power", 0, "Minimum catalog model power for automatic routing")
	maxPower := fs.Int("max-power", 0, "Maximum catalog model power for automatic routing")
	jsonOut := fs.Bool("json", false, "Output JSON")
	overrides := fs.Bool("overrides", false, "Print override_class_breakdown over a time window (ADR-006). "+
		"Operator-driven feedback loop; automatic learning is a future ADR. "+
		"Buckets with high override count and high outcome success rate suggest auto-routing is "+
		"picking suboptimally for that prompt class. Buckets with high override count and low "+
		"outcome success rate suggest users are pinning out of habit; consider UI nudges.")
	since := fs.String("since", "", "Time window for --overrides mode (Go duration, e.g. 24h, 168h). Default 7d (168h).")
	axis := fs.String("axis", "", "With --overrides, filter breakdown rows to overrides on this axis (harness|provider|model).")
	if err := fs.Parse(args); err != nil {
		return 2
	}

	if *overrides {
		return cmdRouteStatusOverrides(workDir, *since, *axis, *jsonOut)
	}
	if err := rootfizeau.ValidatePowerBounds(*minPower, *maxPower); err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 2
	}

	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	svc, err := rootfizeau.New(rootfizeau.ServiceOptions{
		ServiceConfig: agentConfig.NewServiceConfig(cfg, workDir),
		SessionLogDir: sessionLogDir(workDir, cfg),
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	decision, resolveErr := svc.ResolveRoute(ctx, rootfizeau.RouteRequest{
		Profile:  *profile,
		Model:    *model,
		ModelRef: *modelRef,
		Provider: *provider,
		Harness:  *harness,
		MinPower: *minPower,
		MaxPower: *maxPower,
	})

	out := routeStatusOutput{
		Profile:  *profile,
		Model:    *model,
		ModelRef: *modelRef,
		Provider: *provider,
		Harness:  *harness,
		MinPower: *minPower,
		MaxPower: *maxPower,
		PowerPolicy: routeStatusPowerPolicy{
			Profile:  *profile,
			MinPower: *minPower,
			MaxPower: *maxPower,
		},
		Candidates: []routeStatusCandidate{},
	}
	if resolveErr != nil {
		out.Error = resolveErr.Error()
	}
	if decision != nil {
		out.SelectedEndpoint = decision.Endpoint
		out.Sticky = decision.Sticky
		out.Utilization = decision.Utilization
		out.PowerPolicy = routeStatusPowerPolicy{
			Profile:  decision.PowerPolicy.Profile,
			MinPower: decision.PowerPolicy.MinPower,
			MaxPower: decision.PowerPolicy.MaxPower,
		}
		winnerSet := decision.Harness != "" || decision.Provider != "" || decision.Model != ""
		for _, c := range decision.Candidates {
			entry := routeStatusCandidate{
				Harness:       c.Harness,
				Provider:      c.Provider,
				Endpoint:      c.Endpoint,
				Model:         c.Model,
				Score:         c.Score,
				ContextLength: c.ContextLength,
				ContextSource: c.ContextSource,
				Eligible:      c.Eligible,
				FilterReason:  c.FilterReason,
				Reason:        c.Reason,
				CostSource:    c.CostSource,
				Utilization:   c.Utilization,
				Components: routeStatusComponents{
					Power:            c.Components.Power,
					Cost:             c.Components.Cost,
					CostClass:        c.Components.CostClass,
					LatencyMS:        c.Components.LatencyMS,
					SpeedTPS:         c.Components.SpeedTPS,
					SuccessRate:      c.Components.SuccessRate,
					QuotaOK:          c.Components.QuotaOK,
					QuotaPercentUsed: c.Components.QuotaPercentUsed,
					QuotaTrend:       c.Components.QuotaTrend,
					Capability:       c.Components.Capability,
					ContextHeadroom:  c.Components.ContextHeadroom,
				},
			}
			if winnerSet && out.Winner == nil &&
				c.Harness == decision.Harness &&
				c.Provider == decision.Provider &&
				c.Model == decision.Model {
				entry.Winner = true
				w := entry
				out.Winner = &w
			}
			out.Candidates = append(out.Candidates, entry)
		}
	}

	if *jsonOut {
		data, _ := json.MarshalIndent(out, "", "  ")
		fmt.Println(string(data))
		if resolveErr != nil && (decision == nil || decision.Harness == "") {
			return 1
		}
		return 0
	}

	if out.Profile != "" {
		fmt.Printf("Profile: %s\n", out.Profile)
	}
	if out.PowerPolicy.Profile != "" || out.PowerPolicy.MinPower > 0 || out.PowerPolicy.MaxPower > 0 {
		fmt.Printf("Power policy: profile=%s", labelOrUnknown(out.PowerPolicy.Profile))
		if out.PowerPolicy.MinPower > 0 {
			fmt.Printf(" min=%d", out.PowerPolicy.MinPower)
		}
		if out.PowerPolicy.MaxPower > 0 {
			fmt.Printf(" max=%d", out.PowerPolicy.MaxPower)
		}
		fmt.Println()
	}
	if out.Model != "" {
		fmt.Printf("Model: %s\n", out.Model)
	}
	if out.ModelRef != "" {
		fmt.Printf("Model Ref: %s\n", out.ModelRef)
	}
	if out.MinPower > 0 {
		fmt.Printf("Min Power: %d\n", out.MinPower)
	}
	if out.MaxPower > 0 {
		fmt.Printf("Max Power: %d\n", out.MaxPower)
	}
	if out.Winner != nil {
		fmt.Printf("Winner: %s/%s/%s endpoint=%s score=%.2f\n", out.Winner.Harness, out.Winner.Provider, out.Winner.Model, out.Winner.Endpoint, out.Winner.Score)
	}
	if out.SelectedEndpoint != "" {
		fmt.Printf("Selected endpoint: %s\n", out.SelectedEndpoint)
	}
	if out.Sticky.KeyPresent || out.Sticky.Assignment != "" || out.Sticky.Reason != "" {
		fmt.Printf("Sticky: key=%s assignment=%s", stickyLabel(out.Sticky.KeyPresent), labelOrUnknown(out.Sticky.Assignment))
		if out.Sticky.Reason != "" {
			fmt.Printf(" reason=%s", out.Sticky.Reason)
		}
		if out.Sticky.Bonus != 0 {
			fmt.Printf(" bonus=%.2f", out.Sticky.Bonus)
		}
		fmt.Println()
	}
	if out.Utilization.Source != "" || out.Utilization.Freshness != "" || out.Utilization.ActiveRequests != nil || out.Utilization.QueuedRequests != nil || out.Utilization.MaxConcurrency != nil || out.Utilization.CachePressure != nil {
		fmt.Printf("Utilization: source=%s freshness=%s", labelOrUnknown(out.Utilization.Source), labelOrUnknown(out.Utilization.Freshness))
		if out.Utilization.ActiveRequests != nil {
			fmt.Printf(" active=%d", *out.Utilization.ActiveRequests)
		}
		if out.Utilization.QueuedRequests != nil {
			fmt.Printf(" queued=%d", *out.Utilization.QueuedRequests)
		}
		if out.Utilization.MaxConcurrency != nil {
			fmt.Printf(" max=%d", *out.Utilization.MaxConcurrency)
		}
		if out.Utilization.CachePressure != nil {
			fmt.Printf(" cache_pressure=%.2f", *out.Utilization.CachePressure)
		}
		fmt.Println()
	}
	if resolveErr != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", resolveErr)
	}
	fmt.Printf("%-10s %-12s %-14s %-32s %-5s %-5s %-9s %-10s %-10s %-9s %-10s %s\n",
		"HARNESS", "PROVIDER", "ENDPOINT", "MODEL", "ELIG", "POWER", "SCORE", "COST", "LATENCY", "SUCCESS", "SELECTED", "FILTER_REASON")
	for _, c := range out.Candidates {
		elig := "no"
		if c.Eligible {
			elig = "yes"
		}
		selected := "-"
		if c.Winner {
			selected = "yes"
		}
		fmt.Printf("%-10s %-12s %-14s %-32s %-5s %-5d %-9.2f %-10.4f %-10.0f %-9.2f %-10s %s\n",
			c.Harness,
			c.Provider,
			truncate(c.Endpoint, 14),
			truncate(c.Model, 32),
			elig,
			c.Components.Power,
			c.Score,
			c.Components.Cost,
			c.Components.LatencyMS,
			c.Components.SuccessRate,
			selected,
			c.FilterReason,
		)
	}
	if resolveErr != nil && (decision == nil || decision.Harness == "") {
		return 1
	}
	return 0
}

package routehealth

import (
	"sort"
	"strings"
	"sync"
	"time"
)

// DefaultLeaseTTL bounds how long an in-process sticky route lease may live
// without being refreshed.
const DefaultLeaseTTL = 5 * time.Minute

// LeaseKey identifies one sticky lease scope.
type LeaseKey struct {
	StickyKey string
}

// Lease describes one sticky endpoint assignment.
type Lease struct {
	Key         LeaseKey
	Provider    string
	Endpoint    string
	Model       string
	AcquiredAt  time.Time
	RefreshedAt time.Time
	ExpiresAt   time.Time
}

// LeaseInvalidation records why a lease was removed.
type LeaseInvalidation struct {
	Key        LeaseKey
	Provider   string
	Endpoint   string
	Model      string
	Reason     string
	RecordedAt time.Time
}

// LeaseStore owns in-process sticky route assignments. It is safe for
// concurrent use.
type LeaseStore struct {
	mu            sync.Mutex
	leases        map[LeaseKey]Lease
	invalidations map[LeaseKey]LeaseInvalidation
}

// NewLeaseStore returns an empty lease store.
func NewLeaseStore() *LeaseStore {
	return &LeaseStore{
		leases:        make(map[LeaseKey]Lease),
		invalidations: make(map[LeaseKey]LeaseInvalidation),
	}
}

// NormalizeLeaseKey trims whitespace from the sticky key.
func NormalizeLeaseKey(stickyKey string) LeaseKey {
	return LeaseKey{StickyKey: strings.TrimSpace(stickyKey)}
}

// Live returns the current lease for key when it has not expired.
func (s *LeaseStore) Live(now time.Time, key LeaseKey) (Lease, bool) {
	if s == nil {
		return Lease{}, false
	}
	now = normalizeLeaseNow(now)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	lease, ok := s.leases[key]
	if !ok {
		return Lease{}, false
	}
	return lease, true
}

// Acquire stores or refreshes a lease for key.
func (s *LeaseStore) Acquire(now time.Time, ttl time.Duration, key LeaseKey, provider, endpoint, model string) Lease {
	if s == nil {
		return Lease{}
	}
	now = normalizeLeaseNow(now)
	if ttl <= 0 {
		ttl = DefaultLeaseTTL
	}
	key = NormalizeLeaseKey(key.StickyKey)
	provider = strings.TrimSpace(provider)
	endpoint = strings.TrimSpace(endpoint)
	model = strings.TrimSpace(model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)

	lease := Lease{
		Key:         key,
		Provider:    provider,
		Endpoint:    endpoint,
		Model:       model,
		AcquiredAt:  now,
		RefreshedAt: now,
		ExpiresAt:   now.Add(ttl),
	}
	if existing, ok := s.leases[key]; ok {
		if existing.Provider == provider && existing.Endpoint == endpoint && existing.Model == model {
			lease.AcquiredAt = existing.AcquiredAt
		}
	}
	s.leases[key] = lease
	delete(s.invalidations, key)
	return lease
}

// Invalidate removes the lease for key and records the reason.
func (s *LeaseStore) Invalidate(now time.Time, key LeaseKey, reason string) (LeaseInvalidation, bool) {
	if s == nil {
		return LeaseInvalidation{}, false
	}
	now = normalizeLeaseNow(now)
	key = NormalizeLeaseKey(key.StickyKey)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	lease, ok := s.leases[key]
	if !ok {
		return LeaseInvalidation{}, false
	}
	delete(s.leases, key)
	invalidation := LeaseInvalidation{
		Key:        key,
		Provider:   lease.Provider,
		Endpoint:   lease.Endpoint,
		Model:      lease.Model,
		Reason:     strings.TrimSpace(reason),
		RecordedAt: now,
	}
	s.invalidations[key] = invalidation
	return invalidation, true
}

// InvalidateEndpoint removes every lease for the provider/model scope that
// points at the named endpoint and records the supplied reason.
func (s *LeaseStore) InvalidateEndpoint(now time.Time, provider, endpoint, model, reason string) []LeaseInvalidation {
	if s == nil {
		return nil
	}
	now = normalizeLeaseNow(now)
	provider = strings.TrimSpace(provider)
	endpoint = strings.TrimSpace(endpoint)
	model = strings.TrimSpace(model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	if len(s.leases) == 0 {
		return nil
	}
	var out []LeaseInvalidation
	for key, lease := range s.leases {
		if provider != "" && lease.Provider != provider {
			continue
		}
		if endpoint != "" && lease.Endpoint != endpoint {
			continue
		}
		if model != "" && lease.Model != model {
			continue
		}
		delete(s.leases, key)
		invalidation := LeaseInvalidation{
			Key:        key,
			Provider:   lease.Provider,
			Endpoint:   lease.Endpoint,
			Model:      lease.Model,
			Reason:     strings.TrimSpace(reason),
			RecordedAt: now,
		}
		s.invalidations[key] = invalidation
		out = append(out, invalidation)
	}
	return out
}

// LiveByScope returns the live leases for provider/model, ordered by sticky
// key for deterministic tests.
func (s *LeaseStore) LiveByScope(now time.Time, provider, model string) []Lease {
	if s == nil {
		return nil
	}
	now = normalizeLeaseNow(now)
	provider = strings.TrimSpace(provider)
	model = strings.TrimSpace(model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	if len(s.leases) == 0 {
		return nil
	}
	out := make([]Lease, 0, len(s.leases))
	for _, lease := range s.leases {
		if provider != "" && lease.Provider != provider {
			continue
		}
		if model != "" && lease.Model != model {
			continue
		}
		out = append(out, lease)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Endpoint != out[j].Endpoint {
			return out[i].Endpoint < out[j].Endpoint
		}
		return out[i].Key.StickyKey < out[j].Key.StickyKey
	})
	return out
}

// LeaseCounts returns the live lease count per endpoint for provider/model.
func (s *LeaseStore) LeaseCounts(now time.Time, provider, model string) map[string]int {
	leases := s.LiveByScope(now, provider, model)
	if len(leases) == 0 {
		return nil
	}
	counts := make(map[string]int, len(leases))
	for _, lease := range leases {
		counts[lease.Endpoint]++
	}
	return counts
}

// LastInvalidation returns the most recent invalidation recorded for key.
func (s *LeaseStore) LastInvalidation(key LeaseKey) (LeaseInvalidation, bool) {
	if s == nil {
		return LeaseInvalidation{}, false
	}
	key = NormalizeLeaseKey(key.StickyKey)

	s.mu.Lock()
	defer s.mu.Unlock()
	invalidation, ok := s.invalidations[key]
	return invalidation, ok
}

func (s *LeaseStore) expireLocked(now time.Time) {
	for key, lease := range s.leases {
		if lease.ExpiresAt.IsZero() || lease.ExpiresAt.After(now) {
			continue
		}
		delete(s.leases, key)
		s.invalidations[key] = LeaseInvalidation{
			Key:        key,
			Provider:   lease.Provider,
			Endpoint:   lease.Endpoint,
			Model:      lease.Model,
			Reason:     "expired",
			RecordedAt: now,
		}

package routing

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// Request is the routing input. All fields are optional except at least
// one of {Profile, ModelRef, Model, Harness, Provider} should be set
// (otherwise the engine has nothing to disambiguate on).
//
// Provider is present from day one (fixes ddx-8610020e — no soft-preference
// dropping).
type Request struct {
	Profile            string // "cheap" | "standard" | "smart"
	ModelRef           string // catalog alias (e.g. "qwen/qwen3.6")
	Model              string // exact concrete model pin
	Provider           string // exact provider pin; constrains routing to one provider identity
	Harness            string // hard preference; constrains routing to one harness
	Reasoning          string // public reasoning scalar
	Permissions        string // "safe" | "supervised" | "unrestricted"
	ProviderPreference string // "local-first" | "subscription-first" | "local-only" | "subscription-only"
	CorrelationID      string // validated sticky route key, when available

	// EstimatedPromptTokens, when > 0, drives context-window gating.
	EstimatedPromptTokens int

	// RequiresTools, when true, requires the candidate to support tool calling.
	RequiresTools bool
	MinPower      int
	MaxPower      int
}

const (
	ProviderPreferenceLocalFirst        = "local-first"
	ProviderPreferenceSubscriptionFirst = "subscription-first"
	ProviderPreferenceLocalOnly         = "local-only"
	ProviderPreferenceSubscriptionOnly  = "subscription-only"

	ContextSourceProviderAPI    = "provider_api"
	ContextSourceProviderConfig = "provider_config"
	ContextSourceCatalog        = "catalog"
	ContextSourceDefault        = "default"
	ContextSourceUnknown        = "unknown"
)

// MinContextWindow returns the minimum context window the request requires,
// derived from EstimatedPromptTokens with a safety margin.
func (r Request) MinContextWindow() int {
	if r.EstimatedPromptTokens <= 0 {
		return 0
	}
	// 1.25x safety margin for response tokens + tool overhead.
	return r.EstimatedPromptTokens + r.EstimatedPromptTokens/4
}

const (
	QuotaTrendUnknown    = "unknown"
	QuotaTrendHealthy    = "healthy"
	QuotaTrendBurning    = "burning"
	QuotaTrendExhausting = "exhausting"
)

// HarnessEntry is the harness-side input the caller (service) supplies.
// It is the routing engine's view of a registered harness; the engine does
// not import the harnesses package directly to keep the dependency narrow.
type HarnessEntry struct {
	Name                string
	Surface             string
	CostClass           string
	IsLocal             bool
	IsSubscription      bool
	IsHTTPProvider      bool
	AutoRoutingEligible bool
	TestOnly            bool
	ExactPinSupport     bool
	DefaultModel        string
	SupportedModels     []string
	SupportedReasoning  []string
	MaxReasoningTokens  int
	SupportedPerms      []string
	SupportsTools       bool

	// Available reflects the harness's discovered availability.
	Available bool

	// QuotaOK / QuotaPercentUsed reflect live quota state (when applicable).
	// SubscriptionOK gates subscription harnesses at the eligibility level:
	// when false, the candidate is ineligible regardless of score.
	QuotaOK          bool
	QuotaPercentUsed int
	QuotaStale       bool
	QuotaTrend       string // unknown|healthy|burning|exhausting
	QuotaReason      string
	SubscriptionOK   bool // false = hard gate; true = score-based demotion

